package pe.nexo.store.auth;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.Base64;
@Service public class TokenService{private final String secret;private final long expirationSeconds;public TokenService(@Value("${app.jwt.secret}")String secret,@Value("${app.jwt.expiration-seconds:28800}")long expirationSeconds){if(secret==null||secret.length()<32)throw new IllegalStateException("APP_JWT_SECRET debe tener al menos 32 caracteres");this.secret=secret;this.expirationSeconds=expirationSeconds;}public String create(String email){String h=encode("{\"alg\":\"HS256\",\"typ\":\"JWT\"}"),p=encode("{\"sub\":\""+email+"\",\"role\":\"ADMIN\",\"exp\":"+Instant.now().plusSeconds(expirationSeconds).getEpochSecond()+"}"),data=h+"."+p;return data+"."+sign(data);}public boolean valid(String token){try{String[]p=token.split("\\.");if(p.length!=3||!java.security.MessageDigest.isEqual(p[2].getBytes(StandardCharsets.UTF_8),sign(p[0]+"."+p[1]).getBytes(StandardCharsets.UTF_8)))return false;String json=new String(Base64.getUrlDecoder().decode(p[1]),StandardCharsets.UTF_8);long exp=Long.parseLong(json.replaceAll(".*\\\"exp\\\":(\\d+).*","$1"));return exp>Instant.now().getEpochSecond();}catch(Exception ignored){return false;}}private String sign(String value){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}private String encode(String v){return Base64.getUrlEncoder().withoutPadding().encodeToString(v.getBytes(StandardCharsets.UTF_8));}}
